"""Small, self-contained concrete syntax trees for structural code queries."""
import re
from bisect import bisect_right

LANG_ALIASES = {
    'bash':'Bash','sh':'Bash','c':'C','cpp':'Cpp','c++':'Cpp','cxx':'Cpp','cc':'Cpp',
    'csharp':'CSharp','cs':'CSharp','c#':'CSharp','css':'Css','dart':'Dart','elixir':'Elixir','ex':'Elixir',
    'go':'Go','golang':'Go','haskell':'Haskell','hs':'Haskell','hcl':'Hcl','html':'Html','htm':'Html',
    'java':'Java','javascript':'JavaScript','js':'JavaScript','jsx':'JavaScript','json':'Json',
    'kotlin':'Kotlin','kt':'Kotlin','lua':'Lua','nix':'Nix','php':'Php','python':'Python','py':'Python',
    'ruby':'Ruby','rb':'Ruby','rust':'Rust','rs':'Rust','scala':'Scala','solidity':'Solidity','sol':'Solidity',
    'swift':'Swift','tsx':'Tsx','typescript':'TypeScript','ts':'TypeScript','yaml':'Yaml','yml':'Yaml'
}
EXTS = {
    'Bash':['sh','bash','zsh'], 'C':['c','h'], 'Cpp':['cpp','cc','cxx','hpp','hh','hxx','C'],
    'CSharp':['cs'], 'Css':['css'], 'Dart':['dart'], 'Elixir':['ex','exs'], 'Go':['go'],
    'Haskell':['hs'], 'Hcl':['hcl','tf','tfvars'], 'Html':['html','htm'], 'Java':['java'],
    'JavaScript':['js','jsx','mjs','cjs'], 'Json':['json'], 'Kotlin':['kt','kts'], 'Lua':['lua'],
    'Nix':['nix'], 'Php':['php'], 'Python':['py','pyi'], 'Ruby':['rb'], 'Rust':['rs'],
    'Scala':['scala','sc'], 'Solidity':['sol'], 'Swift':['swift'], 'Tsx':['tsx'],
    'TypeScript':['ts','mts','cts'], 'Yaml':['yml','yaml']
}
JS = {'JavaScript','TypeScript','Tsx'}
CISH = {'C','Cpp','Java','CSharp','Dart','Solidity','Kotlin','Scala','Swift'}

class Source:
    def __init__(self, text, lang):
        self.text, self.lang = text, lang
        self.line_starts = [0] + [m.end() for m in re.finditer('\n', text)]
        self.bytes = [0]
        b = 0
        for ch in text:
            b += len(ch.encode('utf-8')); self.bytes.append(b)
    def pos(self, i):
        i = max(0, min(len(self.text), i))
        line = bisect_right(self.line_starts, i)-1
        return {'line':line,'column':i-self.line_starts[line]}
    def range(self, a, b):
        return {'byteOffset':{'start':self.bytes[a],'end':self.bytes[b]},'start':self.pos(a),'end':self.pos(b)}
    def line(self, i):
        if i < 0 or i >= len(self.line_starts): return ''
        a=self.line_starts[i]; b=self.line_starts[i+1]-1 if i+1<len(self.line_starts) else len(self.text)
        return self.text[a:b].rstrip('\r')
    def line_end(self, i):
        return self.line_starts[i+1]-1 if i+1 < len(self.line_starts) else len(self.text)

class Node:
    def __init__(self, kind, start, end, children=None, named=True, field=None, src=None):
        self.kind, self.start, self.end = kind, start, end
        self.children = children or []
        self.named, self.field, self.src = named, field, src
        self.parent = None
        self.meta = None
        for c in self.children: c.parent = self
    @property
    def text(self): return self.src.text[self.start:self.end] if self.src else ''
    def walk(self):
        yield self
        for c in self.children: yield from c.walk()
    def info(self): return {'text':self.text,'range':self.src.range(self.start,self.end)}
    def as_field(self, field): self.field=field; return self
    def __repr__(self): return f'{self.kind}({self.text!r})'

class Token:
    def __init__(self, text, start, end, typ='punct'):
        self.text,self.start,self.end,self.typ=text,start,end,typ
    def __repr__(self): return self.text

OPS = sorted(['===','!==','>>>','>>>=','<<=','>>=','**=','&&=','||=','??=','...','$$$', '?.','=>','==','!=','<=','>=','++','--','&&','||','??','+=','-=','*=','/=','%=','<<','>>','**','//','::','->',':=','<-','..=','..','&=','|=','^=','&.','~='], key=len, reverse=True)

def lex(src):
    s=src.text; lang=src.lang; i=0; out=[]
    while i < len(s):
        ch=s[i]
        if ch.isspace(): i+=1; continue
        start=i
        if (s.startswith('//',i) and lang not in {'Python','Bash','Ruby','Yaml'}) or (ch=='#' and lang in {'Python','Bash','Ruby','Yaml','Nix','Hcl'}):
            j=s.find('\n',i); i=j if j>=0 else len(s); out.append(Token(s[start:i],start,i,'comment')); continue
        if s.startswith('/*',i):
            j=s.find('*/',i+2); i=j+2 if j>=0 else len(s); out.append(Token(s[start:i],start,i,'comment')); continue
        if s.startswith('<!--',i):
            j=s.find('-->',i+4); i=j+3 if j>=0 else len(s); out.append(Token(s[start:i],start,i,'comment')); continue
        if lang in {'Lua','Haskell','Elixir'} and s.startswith('--',i):
            j=s.find('\n',i); i=j if j>=0 else len(s); out.append(Token(s[start:i],start,i,'comment')); continue
        # Python string prefixes are part of the same literal.
        pre=re.match(r'(?i:[rubf]{1,3})(?=[\'\"])',s[i:]) if lang=='Python' else None
        qi=i+len(pre[0]) if pre else i
        if qi<len(s) and s[qi] in '\'"`':
            quote=s[qi]; delim=quote*3 if lang=='Python' and s.startswith(quote*3,qi) else quote
            i=qi+len(delim)
            while i<len(s):
                if s[i]=='\\': i=min(i+2,len(s)); continue
                if s.startswith(delim,i): i+=len(delim); break
                i+=1
            out.append(Token(s[start:i],start,i,'string')); continue
        if ch.isalpha() or ch in '_$' or ord(ch)>127:
            i+=1
            while i<len(s) and (s[i].isalnum() or s[i] in '_$' or ord(s[i])>127): i+=1
            out.append(Token(s[start:i],start,i,'ident')); continue
        if ch.isdigit() or (ch=='.' and i+1<len(s) and s[i+1].isdigit()):
            m=re.match(r'(?:0[xX][\da-fA-F_]+|0[bBoO][\da-fA-F_]+|(?:\d[\d_]*(?:\.[\d_]*)?|\.\d[\d_]*)(?:[eE][+-]?[\d_]+)?)(?:[nufFiI][\w]*)?',s[i:])
            i+=len(m[0]) if m else 1; out.append(Token(s[start:i],start,i,'number')); continue
        op=next((o for o in OPS if s.startswith(o,i)),ch)
        i+=len(op); out.append(Token(op,start,i))
    out.append(Token('',len(s),len(s),'eof'))
    return out

class Parser:
    def __init__(self, src, pattern=False):
        self.src=src; self.lang=src.lang; self.ts=lex(src); self.i=0; self.pattern=pattern; self.error=False
        self.depth=0
    def peek(self, n=0): return self.ts[min(self.i+n,len(self.ts)-1)]
    def at(self,*s): return self.peek().text in s
    def pop(self):
        t=self.peek()
        if self.i < len(self.ts)-1: self.i+=1
        return t
    def token_node(self,t,kind=None,named=None,field=None):
        if named is None: named=t.typ!='punct'
        if kind is None:
            if t.typ=='ident': kind='identifier'
            elif t.typ=='number':
                kind='integer' if self.lang=='Python' and not any(c in t.text for c in '.eEjJ') else 'float' if self.lang=='Python' else 'integer_literal' if self.lang in {'Rust','Java','CSharp'} and not any(c in t.text for c in '.eE') else 'number_literal' if self.lang in {'C','Cpp','Go'} else 'number'
                if self.lang=='Go': kind='float_literal' if '.' in t.text else 'int_literal'
            elif t.typ=='comment': kind='comment'
            elif t.typ=='string': return self.string_node(t)
            else: kind=t.text
        return Node(kind,t.start,t.end,named=named,field=field,src=self.src)
    def take(self, s=None, **kw):
        if s is not None and not self.at(s):
            self.error=True
            t=Token(s,self.peek().start,self.peek().start)
        else:t=self.pop()
        return self.token_node(t,**kw)
    def make(self,kind,children,a=None,b=None):
        children=[c for c in children if c is not None]
        return Node(kind,a if a is not None else (children[0].start if children else self.peek().start), b if b is not None else (children[-1].end if children else self.peek().start), children,src=self.src)
    def newline(self):
        if not self.i: return False
        return '\n' in self.src.text[self.ts[self.i-1].end:self.peek().start]
    def string_node(self,t):
