        return self.get('color','auto') in {'always','ansi'} or (self.get('color','auto')=='auto' and sys.stdout.isatty() and os.environ.get('TERM','dumb')!='dumb' and 'NO_COLOR' not in os.environ)


def config_path(args):
    if args.get('config'):return os.path.abspath(args.get('config'))
    p=Path.cwd()
    while True:
        f=p/'sgconfig.yml'
        if f.exists():return str(f)
        if p==p.parent:break
        p=p.parent
    return None

def read_config(args,required=False):
    path=config_path(args)
    if path:
        try:
            with open(path) as f:text=f.read()
        except OSError as e:error('Cannot read configuration.','Please add an sgconfig.yml configuration file in the project root to run the scan command.','guide/rule-config.html',[os_error(e)],6)
        try:cfg=loads(text)
        except Exception as e:error('Cannot parse configuration file.','Please refer to the configuration documentation and fix the error.','guide/rule-config.html',[str(e)],8)
        if not isinstance(cfg,dict):cfg={}
        return cfg,os.path.dirname(path)
    if required:no_project()
    return None,None

def no_project():error('No ast-grep project configuration is found.','You need to create an ast-grep project for this command. Try `sg new` to create one.','guide/scan-project.html')
def os_error(e):
    if getattr(e,'errno',None)==2:return 'No such file or directory (os error 2)'
    if getattr(e,'errno',None)==13:return 'Permission denied (os error 13)'
    return str(e)

def rule_error(name,e):error('Cannot parse rule '+name,'The file is not a valid ast-grep rule. Please refer to doc and fix the error.','guide/rule-config.html',e.chain if isinstance(e,RuleError) else ['Fail to parse yaml as RuleConfig',str(e)],8)
def rule_not_found(name):error('Rule not found: '+name,f"Rule with id '{name}' not found in project configuration. Please make sure it exists.",'guide/tooling-overview.html#parse-code-from-stdin')

def globmatch(path,pat):
    if isinstance(pat,dict):
        if pat.get('caseInsensitive'):path=path.lower();patt=pat.get('glob','').lower()
        else:patt=pat.get('glob','')
        pat=patt
    if not isinstance(pat,str):return False
    path=path.replace(os.sep,'/');p=pat.lstrip('./') if pat.startswith('./') else pat
    if p.startswith('/'):p=p[1:]
    if p.endswith('/'):p=p.rstrip('/')+'/**'
    # Git-style stars without directory components can match a basename.
    if '/' not in p:return any(fnmatch.fnmatchcase(c,p) for c in path.split('/'))
    if fnmatch.fnmatchcase(path,p):return True
    if p.startswith('**/') and fnmatch.fnmatchcase(path,p[3:]):return True
    return any(fnmatch.fnmatchcase('/'.join(path.split('/')[i:]),p) for i in range(1,len(path.split('/'))))

def glob_filter(path,globs,default=True):
    positives=[g for g in globs if not isinstance(g,str) or not g.startswith('!')]
    match=default if not positives else False
    for g in globs:
        negative=isinstance(g,str) and g.startswith('!');p=g[1:] if negative else g
        if globmatch(path,p):match=not negative
    return match

def file_language(path,cfg=None,prefer=None):
    base=os.path.basename(path)
    if cfg:
        for name,globs in (cfg.get('languageGlobs') or {}).items():
            if any(globmatch(path,g) for g in globs):
                lang=LANG_ALIASES.get(name.lower())
                if lang:return lang
    ext=base.rsplit('.',1)[-1] if '.' in base else ''
    if prefer and ext in EXTS.get(prefer,[]):return prefer
    for lang,exts in EXTS.items():
        if ext in exts:return lang
    return None

def iter_files(paths,args,cfg=None,langs=None):
    noignore=set(args.get('no-ignore',[]));globs=args.get('globs',[]);seen=set()
    ignore_cache={}
    def ignored(file,root):
        if not file:return False
        rel=os.path.relpath(file,root)
        if 'hidden' not in noignore and any(p.startswith('.') and p not in {'.','..'} for p in rel.split(os.sep)):return True
        ignored=False
        parents=[];p=os.path.abspath(os.path.dirname(file));top=os.path.abspath(root)
        while True:
            parents.append(p)
            if p==os.path.dirname(p):break
            if p==top and 'parent' in noignore:break
            p=os.path.dirname(p)
        for d in reversed(parents):
            names=[]
            if 'dot' not in noignore:names.append('.ignore')
            if 'vcs' not in noignore:names.append('.gitignore')
            for name in names:
                f=os.path.join(d,name)
                if f not in ignore_cache:
                    try:ignore_cache[f]=open(f).read().splitlines()
                    except:ignore_cache[f]=[]
                for pattern in ignore_cache[f]:
                    pattern=pattern.strip()
                    if not pattern or pattern.startswith('#'):continue
                    negative=pattern.startswith('!');pattern=pattern[1:] if negative else pattern
                    relp=os.path.relpath(file,d)
                    if globmatch(relp,pattern):ignored=not negative
        return ignored
    def accept(p,root,explicit=False):
        absolute=os.path.abspath(p)
        if absolute in seen:return None
        seen.add(absolute)
        if os.path.islink(p) and not args.get('follow') and not explicit:return None
        lang=file_language(p,cfg,args.get('lang'))
        if langs is not None and lang not in langs:return None
        ig=ignored(p,root) if not explicit else False
        if globs:
            result=glob_filter(os.path.relpath(p,root),globs,not ig)
            if not result:return None
        elif ig:return None
        return p,lang
    for path in paths or ['.']:
        if not os.path.exists(path):
            sys.stderr.write('ERROR: '+path+': No such file or directory (os error 2)\n');continue
        if os.path.isfile(path):
            r=accept(path,os.path.dirname(path) or '.',True)
            if r:yield r
        elif os.path.isdir(path):
            visited=set()
            for root,dirs,files in os.walk(path,followlinks=bool(args.get('follow'))):
                real=os.path.realpath(root)
                if real in visited:dirs[:]=[];continue
                visited.add(real)
                dirs[:]=[d for d in dirs if ('hidden' in noignore or not d.startswith('.')) and (not os.path.islink(os.path.join(root,d)) or args.get('follow')) and not ignored(os.path.join(root,d),path)]
                # Recursive directory iterators naturally return files in reverse insertion order.
                for name in reversed(files):
                    p=os.path.join(root,name)
                    if path=='.' and p.startswith('./'):p=p[2:]
                    r=accept(p,path)
                    if r:yield r

def read_source(path):
    try:
        with open(path,'rb') as f:data=f.read()
        if b'\0' in data:return None
        return data.decode('utf-8')
    except (OSError,UnicodeError):return None

def inspect_project(args,cfg,root):
    if args.get('inspect','nothing')!='nothing':
        sys.stderr.write('sg: summary|project: isProject='+('true,projectDir='+root if cfg is not None else 'false')+'\n')

def pattern_error(e):error('Cannot parse query as a valid pattern.','The pattern either fails to parse or contains error. Please refer to pattern syntax guide.','guide/pattern-syntax.html',[str(e)],8)

def write_results(matches,args,is_scan=False):
    if args.get('json'):
        sys.stdout.write(json_output(matches,args.get('json'),args.before(),args.after(),args.get('include-metadata',False)));return
    if args.get('files-with-matches'):
        seen=set()
        for m in matches:
            if m.file not in seen:sys.stdout.write(m.file+'\n');seen.add(m.file)
        return
    if args.get('format')=='github':sys.stdout.write(github_output(matches));return
    if args.get('format')=='sarif':sys.stdout.write(sarif_output(matches));return
    if args.get('update-all'):
        files={}
        for m in matches:files.setdefault(m.file,[]).append(m)
        total=0
        for file,mm in files.items():
            source=mm[0].node.src.text;new,count=apply_edits(source,mm);total+=count
            if count:
                if file=='STDIN':sys.stdout.write(new+'\n')
                else:
                    with open(file,'w',newline='') as f:f.write(new)
            elif is_scan:
                for m in mm:sys.stdout.write(diagnostic(m,args.get('report-style','rich'),args.color()))
        if total:sys.stderr.write(f'Applied {total} changes\n')
        return
    if is_scan:
        for m in matches:sys.stdout.write(diagnostic(m,args.get('report-style','rich'),args.color()))
    elif args.get('rewrite') is not None:
        files={}
        for m in matches:files.setdefault(m.file,[]).append(m)
        for file,mm in files.items():
            src=mm[0].node.src.text;new,count=apply_edits(src,mm)
            sys.stdout.write(diff_output(src,new,file,args.color()))
    else:
        heading=args.get('heading','auto')=='always' or (args.get('heading','auto')=='auto' and sys.stdout.isatty())
        sys.stdout.write(search_output(matches,heading,args.before(),args.after(),args.color()))

def run(args):
    if args.get('stdin') and not args.get('lang'):error('Language must be specified for code from StdIn.','Please use `--lang` to specify the code language.','guide/tooling-overview.html#parse-code-from-stdin')
    if args.get('stdin') and args.get('interactive'):error('Interactive mode is incompatible with parsing code from StdIn.','`--interactive` needs StdIn, but it is used as source code. Please use files as input.','guide/tooling-overview.html#parse-code-from-stdin',code=7)
    cfg,root=read_config(args);inspect_project(args,cfg,root)
    lang=args.get('lang');patterns={};matches=[];scanned=0;skipped=0
    if lang:
        try:patterns[lang]=Pattern(args.get('pattern'),lang,args.get('selector'),args.get('strictness','smart'))
        except PatternError as e:pattern_error(e)
        if args.get('debug-query'):sys.stderr.write(patterns[lang].debug(args.get('debug-query')))
    if args.get('stdin'):files=[('STDIN',lang,sys.stdin.read())]
    else:files=((f,l,None) for f,l in iter_files(args.paths,args,cfg,{lang} if lang else None))
    for file,language,source in files:
        if file!='STDIN':scanned+=1
        if language is None:continue
        if args.get('inspect')=='entity' and file!='STDIN':sys.stderr.write(f'sg: entity|file|{file}: language={language}\n')
        if source is None:source=read_source(file)
        if source is None:continue
        if language not in patterns:
            try:patterns[language]=Pattern(args.get('pattern'),language,args.get('selector'),args.get('strictness','smart'))
            except PatternError:patterns[language]=None
        pat=patterns[language]
        if pat is None:continue
        try:tree,err=parse(source,language)
        except Exception:continue
        for node in tree.walk():
            env=Env()
            if pat.kinds is not None and node.kind not in pat.kinds:continue
            if pat.match(node,env):matches.append(Match(node,file,env,get_edit(args.get('rewrite'),node,env,language)))
    write_results(matches,args)
    if args.get('inspect','nothing')!='nothing':sys.stderr.write(f'sg: summary|file: scannedFileCount={scanned},skippedFileCount={skipped}\n')
    if not matches and any(p and p.error for p in patterns.values()):
        sys.stderr.write('Warning: Pattern contains an ERROR node and may cause unexpected results.\nHelp: ast-grep parsed the pattern but it matched nothing in this run. Try using playground to refine the pattern.\nSee also: https://ast-grep.github.io/playground.html\n\n');return 0
    return 0 if matches else 1

def load_rules(args,cfg,root,for_test=False):
    files=[];rules=[];utils={}
    if cfg:
        for ud in cfg.get('utilDirs') or []:
            path=os.path.join(root,ud)
            for base,ds,fs in os.walk(path):
                for name in fs:
                    if not name.endswith(('.yml','.yaml')):continue
                    try:
                        for obj in loads_all(open(os.path.join(base,name)).read()):
                            if isinstance(obj,dict) and 'id' in obj:utils[obj['id']]=obj.get('rule',{})
                    except:pass
    if args.get('inline-rules') is not None:files.append(('INLINE_RULES',args.get('inline-rules')))
    elif args.get('rule'):
        path=args.get('rule')
        try:text=open(path).read()
        except OSError as e:error('Cannot read rule '+path,'The rule file either does not exist or cannot be opened.','guide/rule-config.html',[os_error(e)],6)
        files.append((path,text))
    else:
        if cfg is None:no_project()
        for d in cfg.get('ruleDirs') or []:
            path=os.path.join(root,d)
            if not os.path.isdir(path):
                continue
            for base,ds,fs in os.walk(path):
                ds[:]=[d for d in ds if not d.startswith('.')]
                for name in sorted(fs):
                    if name.endswith(('.yml','.yaml')):
                        p=os.path.join(base,name)
                        try:files.append((p,open(p).read()))
                        except OSError as e:error('Cannot read rule '+p,'The rule file either does not exist or cannot be opened.','guide/rule-config.html',[os_error(e)],6)
    skipped=0
    for name,text in files:
        try:
            objs=loads_all(text)
            for obj in objs:
                r=RuleConfig(obj,utils)
                if args.get('filter'):
                    try:ok=re.search(args.get('filter'),r.id)
                    except:ok=False
                    if not ok:skipped+=1;continue
                for sev in ['off','hint','info','warning','error']:
                    values=args.get(sev,[])
                    if '' in values or r.id in values or any(r.id in v.split(',') for v in values):r.severity=sev
                if r.severity=='off' and not (args.get('rule') or args.get('inline-rules') is not None or (for_test and args.get('include-off'))):skipped+=1;continue
                rules.append(r)
        except (RuleError,YamlError,TypeError,ValueError) as e:rule_error(name,e)
    if for_test and args.get('filter') and not rules:rule_not_found(args.get('filter'))
    return rules,skipped

def scan(args):
    if args.get('stdin') and not (args.get('rule') or args.get('inline-rules') is not None):error('Only one rule can scan code from StdIn.','Please use `--rule path/to/rule.yml` to choose the rule.','guide/tooling-overview.html#parse-code-from-stdin')
    if args.get('stdin') and args.get('interactive'):error('Interactive mode is incompatible with parsing code from StdIn.','`--interactive` needs StdIn, but it is used as source code. Please use files as input.','guide/tooling-overview.html#parse-code-from-stdin',code=7)
    cfg,root=read_config(args,not(args.get('rule') or args.get('inline-rules') is not None));inspect_project(args,cfg,root)
    rules,skippedrules=load_rules(args,cfg,root);matches=[];scanned=0
    if args.get('inspect')=='entity':
        for r in rules:sys.stderr.write(f'sg: entity|rule|{r.id}: finalSeverity={r.severity.title()}\n')
    if args.get('stdin'):files=[('STDIN',rules[0].language if rules else None,sys.stdin.read())]
    else:files=((f,l,None) for f,l in iter_files(args.paths,args,cfg,{r.language for r in rules}))
    for file,lang,source in files:
        if lang is None:continue
        if file!='STDIN':scanned+=1
        if source is None:source=read_source(file)
        if source is None:continue
        try:tree,err=parse(source,lang)
        except Exception:continue
        frules=[]
        for r in rules:
            if r.language!=lang and file!='STDIN':continue
            relative=os.path.relpath(os.path.abspath(file),root or os.getcwd()) if file!='STDIN' else file
            if file!='STDIN' and r.data.get('files') and not any(globmatch(relative,g) for g in r.data['files']):continue
            if file!='STDIN' and any(globmatch(relative,g) for g in r.data.get('ignores') or []):continue
            frules.append(r)
        if args.get('inspect')=='entity' and file!='STDIN':sys.stderr.write(f'sg: entity|file|{file}: language={lang},effectiveRuleCount={len(frules)},skippedRuleCount={len(rules)-len(frules)}\n')
        for r in frules:
            if file=='STDIN' and r.language!=lang:tree,err=parse(source,r.language)
            for n in tree.walk():
                if r.rule.kinds is not None and n.kind not in r.rule.kinds:continue
                env=Env()
                if r.match(n,env):
                    matches.append(Match(n,file,env,get_edit(r.fix,n,env,r.language),r))
                    if args.get('max-results') is not None and len(matches)>=args.get('max-results'):break
            if args.get('max-results') is not None and len(matches)>=args.get('max-results'):break
        if args.get('max-results') is not None and len(matches)>=args.get('max-results'):break
    write_results(matches,args,True)
    if args.get('inspect','nothing')!='nothing' and not args.get('stdin'):
        sys.stderr.write(f'sg: summary|file: scannedFileCount={scanned},skippedFileCount=0\nsg: summary|rule: effectiveRuleCount={len(rules)},skippedRuleCount={skippedrules}\n')
    errors=sum(m.rule.severity=='error' for m in matches)
    if errors:error(f'{errors} error(s) found in code.','Scan succeeded and found error level diagnostics in the codebase.',code=1)
    return 0


def sarif_output(matches):
    rules=[];ids={};results=[]
    for m in matches:
        r=m.rule
        if r.id not in ids:
            ids[r.id]=len(rules);rules.append({'id':r.id,'shortDescription':{'text':r.message},'defaultConfiguration':{'level':{'hint':'note','info':'note','warning':'warning','error':'error','off':'none'}[r.severity]}})
        pos=m.node.src.pos(m.node.start);end=m.node.src.pos(m.node.end)
