def new(args):
    cfg,root=read_config(args);sub=args.subcommand
    if not sub:
        sub='project' if cfg is None else 'rule'
    name=args.paths[0] if args.paths else None;lang=args.get('lang')
    if sub=='project':
        if cfg is not None:error('ast-grep project already exists.','You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?','guide/scan-project.html',code=17)
        sys.stdout.write('Creating a new ast-grep project...\n')
        root=os.getcwd();r=os.path.join(root,'rules');t=os.path.join(root,'rule-tests');u=os.path.join(root,'utils')
        for d in [r,t,u]:os.makedirs(d,exist_ok=True);open(os.path.join(d,'.gitkeep'),'a').close()
        path=args.get('config') or 'sgconfig.yml'
        with open(path,'w') as f:f.write(f'ruleDirs:\n- {r}\ntestConfigs:\n- testDir: {t}\nutilDirs:\n- {u}\n')
        sys.stdout.write('Your new ast-grep project has been created!\n');return 0
